require_once 'db.php';require_once 'auth.php';bejelentkezesSzukseges();$id=(int)($_GET['id']??0);function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function ido($v){return $v?substr($v,0,5):'—';}
$st=$pdo->prepare("SELECT b.*,r.riasztas_szam,r.datum,r.riasztasi_ido,r.helyszin,r.telepules,r.esemeny_tipus,r.leiras,r.jelzes_modja,r.allapot,r.lezaras_ido,r.megjegyzes AS riasztas_megjegyzes,j.azonosito AS jarmu_azonosito,j.rendszam,j.marka,j.tipus,j.evjarat,j.uzemanyag,j.statusz AS jarmu_statusz FROM bevetesek b LEFT JOIN riasztasok r ON r.id=b.riasztas_id LEFT JOIN jarmuvek j ON j.id=b.jarmu_id WHERE b.id=? LIMIT 1");$st->execute([$id]);$b=$st->fetch();if(!$b)exit('A bevetés nem található.');$st=$pdo->prepare("SELECT bt.*,t.teljes_nev,t.becenev,t.beosztas FROM bevetes_tagok bt LEFT JOIN tagok t ON t.id=bt.tag_id WHERE bt.bevetes_id=? ORDER BY t.teljes_nev ASC");$st->execute([$id]);$tagok=$st->fetchAll();$oldalCim='Bevetési adatlap';require 'header.php';?><div class="print-toolbar"><a href="bevetesek.php" class="btn btn-light">← Vissza</a><a href="bevetes_szerkeszt.php?id=<?=$id?>" class="btn btn-secondary">Szerkesztés</a><button onclick="window.print()" class="btn btn-primary">🖨 Nyomtatás</button></div><div class="report-sheet"><div class="report-head"><div><div class="report-brand"><span class="logo-mark">SZ</span><strong>SZÖTE</strong></div><span class="eyebrow">ÖNKÉNTES TŰZOLTÓ EGYESÜLET</span></div><div class="report-title">BEVETÉSI<br>ADATLAP</div></div><div class="report-meta"><div><span>Riasztási szám</span><strong><?=e($b['riasztas_szam'])?></strong></div><div><span>Dátum</span><strong><?=e($b['datum'])?></strong></div><div><span>Riasztási idő</span><strong><?=ido($b['riasztasi_ido'])?></strong></div><div><span>Állapot</span><strong><?=e($b['allapot'])?></strong></div></div><section class="report-section"><h2>Esemény adatai</h2><div class="report-grid"><div><span>Helyszín</span><strong><?=e($b['helyszin'])?></strong></div><div><span>Település</span><strong><?=e($b['telepules']?:'—')?></strong></div><div><span>Esemény típusa</span><strong><?=e($b['esemeny_tipus'])?></strong></div><div><span>Jelzés módja</span><strong><?=e($b['jelzes_modja']?:'—')?></strong></div></div><?php if($b['leiras']):?><div class="report-note"><span>Leírás</span><p><?=nl2br(e($b['leiras']))?></p></div><?php endif;?></section><section class="report-section"><h2>Bevetési időadatok</h2><div class="timeline"><div><span>Indulás</span><strong><?=ido($b['indulas_ido'])?></strong></div><div><span>Érkezés</span><strong><?=ido($b['erkezes_ido'])?></strong></div><div><span>Visszaindulás</span><strong><?=ido($b['visszaindulas_ido'])?></strong></div><div><span>Visszaérkezés</span><strong><?=ido($b['visszaerkezes_ido'])?></strong></div></div></section><section class="report-section"><h2>Jármű</h2><?php if($b['jarmu_azonosito']):?><div class="report-grid"><div><span>Azonosító</span><strong><?=e($b['jarmu_azonosito'])?></strong></div><div><span>Rendszám</span><strong><?=e($b['rendszam']?:'—')?></strong></div><div><span>Jármű</span><strong><?=e(trim($b['marka'].' '.$b['tipus']))?></strong></div><div><span>Állapot</span><strong><?=e($b['jarmu_statusz'])?></strong></div></div><?php else:?><p class="muted">Jármű nincs rögzítve.</p><?php endif;?></section><section class="report-section"><h2>Kivonult személyi állomány</h2><div class="table-wrap"><table><thead><tr><th>Név</th><th>Beosztás</th><th>Szerep</th><th>Megjegyzés</th></tr></thead><tbody><?php foreach($tagok as $t):?><tr><td><strong><?=e($t['teljes_nev'])?></strong><?= $t['becenev']?' ('.e($t['becenev']).')':'' ?></td><td><?=e($t['beosztas']?:'—')?></td><td><?=e($t['szerep']?:'—')?></td><td><?=e($t['megjegyzes']?:'—')?></td></tr><?php endforeach;if(!$tagok):?><tr><td colspan="4">Nincs személy rögzítve.</td></tr><?php endif;?></tbody></table></div></section><?php if($b['megjegyzes']):?><section class="report-section"><h2>Bevetési megjegyzés</h2><p><?=nl2br(e($b['megjegyzes']))?></p></section><?php endif;?><section class="signature-grid"><div><span>Parancsnok / szolgálatvezető</span></div><div><span>Gépjárművezető</span></div><div><span>Adatlapot rögzítette</span></div></section><div class="report-foot">Bevetés azonosító: #<?=e($b['id'])?> · Létrehozva: <?=e($b['letrehozva'])?> · Módosítva: <?=e($b['modositva'])?></div></div><?php require 'footer.php';?>